33	     * Creates a config loader from YAML section readers.
34	     */
35	    public function __construct(
36	        ?ConfigStringListReader $stringListReader = null,
37	        ?LimitConfigReader $limitConfigReader = null,
38	        ?ReportConfigReader $reportConfigReader = null,
39	    ) {
40	        $this->stringListReader = $stringListReader ?? new ConfigStringListReader();
41	        $this->limitConfigReader = $limitConfigReader ?? new LimitConfigReader();
42	        $this->reportConfigReader = $reportConfigReader ?? new ReportConfigReader();
43	    }
44	
45	    /**
46	     * Loads and validates a LocGuard YAML configuration file.
47	     */
48	    public function load(string $path): LocGuardConfig
49	    {
50	        if (!is_file($path)) {
51	            throw new LocGuardException(sprintf('LocGuard config not found: %s', $path));
52	        }
53	
54	        try {
55	            $data = Yaml::parseFile($path);
56	        } catch (ParseException $exception) {
57	            throw new LocGuardException('Invalid loc.yaml: ' . $exception->getMessage(), 0, $exception);
58	        }
59	
60	        if (!is_array($data)) {
61	            throw new LocGuardException('Invalid loc.yaml: top-level value must be a mapping.');
62	        }
63	
64	        return new LocGuardConfig(
65	            dirname($path),
66	            $this->stringListReader->read($data, 'paths', ['src']),
67	            $this->stringListReader->read($data, 'exclude', []),
68	            $this->limitConfigReader->read($data['limits'] ?? []),
69	            $this->reportConfigReader->read($data['report'] ?? []),
70	        );
