13	/**
14	 * Parses LocGuard command-line arguments.
15	 */
16	final class LocGuardCliArgumentParser
17	{
18	    /**
19	     * Parses LocGuard flags and options.
20	     *
21	     * @param list<string> $argv
22	     * @return array{config: string, help: bool, reporter: ?string, version: bool}
23	     */
24	    public function parse(array $argv): array
25	    {
26	        $arguments = ['config' => 'loc.yaml', 'help' => false, 'reporter' => null, 'version' => false];
27	
28	        for ($index = 0; $index < count($argv); $index++) {
29	            $arg = $argv[$index];
30	            if ($arg === '--help' || $arg === '-h') {
31	                $arguments['help'] = true;
32	            } elseif ($arg === '--version' || $arg === '-V') {
33	                $arguments['version'] = true;
34	            } elseif ($arg === '--config') {
35	                if (!isset($argv[$index + 1]) || str_starts_with($argv[$index + 1], '-')) {
36	                    throw new LocGuardException(sprintf('Missing value for %s.', '--config'));
37	                }
38	                $arguments['config'] = $argv[++$index];
39	            } elseif (str_starts_with($arg, '--config=')) {
40	                $arguments['config'] = substr($arg, 9);
41	            } elseif ($arg === '--reporter' || $arg === '--format') {
42	                if (!isset($argv[$index + 1]) || str_starts_with($argv[$index + 1], '-')) {
43	                    throw new LocGuardException(sprintf('Missing value for %s.', $arg));
44	                }
45	                $arguments['reporter'] = $argv[++$index];
46	            } elseif (str_starts_with($arg, '--reporter=')) {
47	                $arguments['reporter'] = substr($arg, 11);
48	            } elseif (str_starts_with($arg, '--format=')) {
49	                $arguments['reporter'] = substr($arg, 9);
50	            } else {
51	                throw new LocGuardException(sprintf('Unknown option: %s', $arg));
52	            }
53	        }
54	
55	        return $arguments;
56	    }
57	}
