22	    /** @readonly */
23	    private LocGuardReporterOverride $reporterOverride;
24	
25	    /**
26	     * Creates an analysis runner from LocGuard services.
27	     */
28	    public function __construct(
29	        /** @readonly */
30	        private string $workingDirectory,
31	        /** @readonly */
32	        private ConfigLoader $configLoader,
33	        /** @readonly */
34	        private LocGuardAnalyzer $analyzer,
35	        /** @readonly */
36	        private ReporterFactory $reporterFactory,
37	        /** @readonly */
38	        private LocGuardOutputWriter $writer,
39	        ?LocGuardConfigPathResolver $pathResolver = null,
40	        ?LocGuardReporterOverride $reporterOverride = null,
41	    ) {
42	        $this->pathResolver = $pathResolver ?? new LocGuardConfigPathResolver();
43	        $this->reporterOverride = $reporterOverride ?? new LocGuardReporterOverride();
44	    }
45	
46	    /**
47	     * Runs analysis and writes the selected report.
48	     */
49	    public function run(string $configPath, ?string $reporterOverride): int
50	    {
51	        try {
52	            $config = $this->configLoader->load($this->pathResolver->resolve($this->workingDirectory, $configPath));
53	            $config = $this->reporterOverride->apply($config, $reporterOverride);
