15	/**
16	 * Reads LocGuard report configuration from loc.yaml.
17	 */
18	final class ReportConfigReader
19	{
20	    /** @var list<string> */
21	    private const REPORTERS = ['ai', 'text', 'json'];
22	
23	    /** @var list<string> */
24	    private const ORDER_FIELDS = ['path', 'line', 'rule', 'actual', 'limit'];
25	
26	    /** @readonly */
27	    private ConfigScalarReader $scalarReader;
28	
29	    /** @readonly */
30	    private ConfigStringListReader $stringListReader;
31	
32	    /**
33	     * Creates a reader from scalar and list validation.
34	     */
35	    public function __construct(
36	        ?ConfigScalarReader $scalarReader = null,
37	        ?ConfigStringListReader $stringListReader = null,
38	    ) {
39	        $this->scalarReader = $scalarReader ?? new ConfigScalarReader();
40	        $this->stringListReader = $stringListReader ?? new ConfigStringListReader();
41	    }
42	
43	    /**
44	     * Reads report output configuration.
45	     *
46	     * @param mixed $value
47	     */
48	    public function read($value): ReportConfig
49	    {
50	        if (!is_array($value)) {
51	            throw new LocGuardException('Invalid loc.yaml: "report" must be a mapping.');
52	        }
53	
54	        $reporter = $this->scalarReader->string($value, 'reporter', 'ai');
55	        if (!in_array($reporter, self::REPORTERS, true)) {
56	            throw new LocGuardException(sprintf('Invalid loc.yaml: "report.reporter" must be one of: %s.', implode(', ', self::REPORTERS)));
57	        }
58	
59	        $orderBy = $this->stringListReader->read($value, 'order_by', ['path', 'line', 'rule']);
60	        foreach ($orderBy as $field) {
61	            if (!in_array($field, self::ORDER_FIELDS, true)) {
62	                throw new LocGuardException(sprintf('Invalid loc.yaml: "report.order_by" contains unsupported field "%s".', $field));
63	            }
64	        }
65	
66	        return new ReportConfig($reporter, $orderBy);
67	    }
68	}
