15	    /** @readonly */
16	    private ViolationSorter $sorter;
17	
18	    /** @readonly */
19	    private AiReportSummary $summary;
20	
21	    /** @readonly */
22	    private AiReportGuidance $guidance;
23	
24	    /** @readonly */
25	    private AiViolationFormatter $violationFormatter;
26	
27	    /**
28	     * Creates an AI reporter with violation ordering support.
29	     */
30	    public function __construct(
31	        ?ViolationSorter $sorter = null,
32	        ?AiReportSummary $summary = null,
33	        ?AiReportGuidance $guidance = null,
34	        ?AiViolationFormatter $violationFormatter = null,
35	    ) {
36	        $this->sorter = $sorter ?? new ViolationSorter();
37	        $this->summary = $summary ?? new AiReportSummary();
38	        $this->guidance = $guidance ?? new AiReportGuidance();
39	        $this->violationFormatter = $violationFormatter ?? new AiViolationFormatter();
40	    }
41	
42	    /**
43	     * Formats a structured report intended for AI coding agents.
44	     */
45	    public function report(AnalysisResult $result, ReportConfig $config): string
46	    {
47	        $output = $result->hasViolations() ? "LOC_GUARD_FAILED\n" : "LOC_GUARD_PASSED\n";
48	        $output .= $this->summary->summary($result);
49	
50	        if (!$result->hasViolations()) {
51	            return $output;
52	        }
53	
54	        $output .= $this->guidance->guidance();
55	        foreach ($this->sorter->sort($result->violations, $config) as $index => $violation) {
56	            $output .= $this->violationFormatter->format($index + 1, $violation);
57	        }
58	
59	        return $output;
60	    }
61	}
