12	/**
13	 * Sorts violations according to LocGuard report ordering configuration.
14	 */
15	final class ViolationSorter
16	{
17	    /** @readonly */
18	    private ViolationFieldComparator $fieldComparator;
19	
20	    /**
21	     * Creates a sorter from field comparison behavior.
22	     */
23	    public function __construct(?ViolationFieldComparator $fieldComparator = null)
24	    {
25	        $this->fieldComparator = $fieldComparator ?? new ViolationFieldComparator();
26	    }
27	
28	    /**
29	     * Returns violations sorted by configured fields.
30	     *
31	     * @param list<Violation> $violations
32	     * @return list<Violation>
33	     */
34	    public function sort(array $violations, ReportConfig $config): array
35	    {
36	        usort($violations, function (Violation $left, Violation $right) use ($config): int {
37	            foreach ($config->orderBy as $field) {
38	                $comparison = $this->fieldComparator->compare($left, $right, $field);
39	                if ($comparison !== 0) {
40	                    return $comparison;
41	                }
42	            }
43	
44	            return 0;
45	        });
46	
47	        return $violations;
48	    }
49	}
