15	final class LocGuardPathResolver
16	{
17	    /**
18	     * Returns an absolute path for a configured source path.
19	     */
20	    public function absolute(string $root, string $path): string
21	    {
22	        if (str_starts_with($path, '/')) {
23	            return rtrim($path, '/');
24	        }
25	
26	        return rtrim($root . '/' . $path, '/');
27	    }
