40	    /**
41	     * Returns PHP files under the configured path.
42	     *
43	     * @return array<string, string>
44	     */
45	    public function files(LocGuardConfig $config, string $path): array
46	    {
47	        if (is_file($path)) {
48	            return $this->inclusionPolicy->includes($config, $path) ? [$path => $this->pathResolver->relative($config->root, $path)] : [];
49	        }
50	
51	        if (!is_dir($path)) {
52	            throw new LocGuardException(sprintf('Configured path does not exist: %s', $path));
53	        }
54	
55	        $files = [];
56	        $iterator = new RecursiveIteratorIterator(
57	            new RecursiveDirectoryIterator($path, RecursiveDirectoryIterator::SKIP_DOTS),
58	        );
59	
60	        /** @var SplFileInfo $item */
